/* HEXA BATTLEGROUNDS setup — PART 73 OF 82. Run parts in order. Safe to re-run. */ insert into mission_templates(id, family, kind, title, category, difficulty, tags, objective, clues, parts, relay, attempts, time_limit, hint, explanation, points, coins, status) values ('airdrop-codebreak-60', 'codebreak', 'airdrop', 'Code Breaker', 'logic', 1, array['any']::text[], 'Someone already tried to open this keypad. Intel has their tries and the keypad''s answers, Decoder knows what the lights mean, Scout found one fact about the code.', '{"intel":{"title":"Earlier tries","body":"4 2 6   →   ○\n4 3 2   →   —\n1 3 4   →   —\n1 3 7   →   —","big":true},"decoder":{"title":"What the lights mean","body":"● = a right digit in the right place\n○ = a right digit in the wrong place\n— = no digit right\nThe code has 3 different digits from 1 to 8."},"scout":{"title":"What you found","body":"The FIRST digit is odd."}}'::jsonb, '[{"label":"3-digit code","accept":["568"]}]'::jsonb, false, 3, 150, 'Start with the try that has no lights at all: those digits are out. Then use the ● tries to pin positions. Scout''s fact settles the last choice.', 'secret 568 (The FIRST digit is odd.)', null, 25, 'published'), ('airdrop-codebreak-61', 'codebreak', 'airdrop', 'Code Breaker', 'logic', 2, array['any']::text[], 'Someone already tried to open this keypad. Intel has their tries and the keypad''s answers, Decoder knows what the lights mean, Scout found one fact about the code.', '{"intel":{"title":"Earlier tries","body":"5 3 8   →   ○\n3 2 7   →   —\n2 8 6   →   ●○\n3 6 7   →   ○\n5 1 4   →   ○","big":true},"decoder":{"title":"What the lights mean","body":"● = a right digit in the right place\n○ = a right digit in the wrong place\n— = no digit right\nThe code has 3 different digits from 1 to 8."},"scout":{"title":"What you found","body":"The digits add up to an EVEN number."}}'::jsonb, '[{"label":"3-digit code","accept":["846"]}]'::jsonb, false, 3, 150, 'Start with the try that has no lights at all: those digits are out. Then use the ● tries to pin positions. Scout''s fact settles the last choice.', 'secret 846 (The digits add up to an EVEN number.)', null, 25, 'published'), ('airdrop-codebreak-62', 'codebreak', 'airdrop', 'Code Breaker', 'logic', 1, array['any']::text[], 'Someone already tried to open this keypad. Intel has their tries and the keypad''s answers, Decoder knows what the lights mean, Scout found one fact about the code.', '{"intel":{"title":"Earlier tries","body":"2 7 5   →   ○\n3 6 5   →   —\n8 2 1   →   ●○\n6 1 4   →   ○","big":true},"decoder":{"title":"What the lights mean","body":"● = a right digit in the right place\n○ = a right digit in the wrong place\n— = no digit right\nThe code has 3 different digits from 1 to 8."},"scout":{"title":"What you found","body":"The LAST digit is bigger than the first."}}'::jsonb, '[{"label":"3-digit code","accept":["428"]}]'::jsonb, false, 3, 150, 'Start with the try that has no lights at all: those digits are out. Then use the ● tries to pin positions. Scout''s fact settles the last choice.', 'secret 428 (The LAST digit is bigger than the first.)', null, 25, 'published'), ('airdrop-codebreak-63', 'codebreak', 'airdrop', 'Code Breaker', 'logic', 1, array['any']::text[], 'Someone already tried to open this keypad. Intel has their tries and the keypad''s answers, Decoder knows what the lights mean, Scout found one fact about the code.', '{"intel":{"title":"Earlier tries","body":"8 6 5   →   ○\n7 1 4   →   ●○\n6 2 3   →   —","big":true},"decoder":{"title":"What the lights mean","body":"● = a right digit in the right place\n○ = a right digit in the wrong place\n— = no digit right\nThe code has 3 different digits from 1 to 8."},"scout":{"title":"What you found","body":"The code has NO digit above 6."}}'::jsonb, '[{"label":"3-digit code","accept":["154"]}]'::jsonb, false, 3, 150, 'Start with the try that has no lights at all: those digits are out. Then use the ● tries to pin positions. Scout''s fact settles the last choice.', 'secret 154 (The code has NO digit above 6.)', null, 25, 'published'), ('mission-scales-0', 'scales', 'mission', 'Balance Scales', 'maths', 1, array['food','market','coffee','social','any']::text[], 'The canteen store-room scales are balanced. Scout sees them, Intel knows one weight, Decoder has the delivery note.', '{"scout":{"title":"The two scales","body":"Scale 1:  🍉🍉   ⚖   🍇\nScale 2:  🍇🍉🍉   ⚖   🍎","big":true},"intel":{"title":"Known weight","body":"One melon 🍉 weighs 4 kg."},"decoder":{"title":"Delivery note","body":"How many kg is this box?   🍉 + 🍇 + 🍎"}}'::jsonb, '[{"label":"Weight in kg","accept":["28"]}]'::jsonb, false, 3, 200, 'Work out B from scale 1, then C from scale 2, then add up the box.', 'melon=4, grapes=8, apple=16 → 28', null, 25, 'published'), ('mission-scales-1', 'scales', 'mission', 'Balance Scales', 'maths', 1, array['food','market','coffee','social','any']::text[], 'The canteen store-room scales are balanced. Scout sees them, Intel knows one weight, Decoder has the delivery note.', '{"scout":{"title":"The two scales","body":"Scale 1:  🍇🍇🍇   ⚖   📦\nScale 2:  📦🍇   ⚖   🍍","big":true},"intel":{"title":"Known weight","body":"One grapes 🍇 weighs 3 kg."},"decoder":{"title":"Delivery note","body":"How many kg is this box?   🍇 + 🍍🍍"}}'::jsonb, '[{"label":"Weight in kg","accept":["27"]}]'::jsonb, false, 3, 200, 'Work out B from scale 1, then C from scale 2, then add up the box.', 'grapes=3, parcel=9, pineapple=12 → 27', null, 25, 'published') on conflict (id) do update set family = excluded.family, kind = excluded.kind, title = excluded.title, category = excluded.category, difficulty = excluded.difficulty, tags = excluded.tags, objective = excluded.objective, clues = excluded.clues, parts = excluded.parts, relay = excluded.relay, attempts = excluded.attempts, time_limit = excluded.time_limit, hint = excluded.hint, explanation = excluded.explanation, points = excluded.points, coins = excluded.coins, status = excluded.status, version = 